using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Runtime.InteropServices.WindowsRuntime;using System.Threading;using System.Threading.Tasks;
using Windows.Globalization;using Windows.Graphics.Imaging;using Windows.Media.Ocr;

namespace AgitCon {
    internal sealed class ConfirmationReading {internal int State;internal string Stage;internal static ConfirmationReading Unknown(string stage){return new ConfirmationReading{Stage=stage};}}
    internal static class ConfirmationVision {
        internal const string Label="파일 전송 시 확인하고 보내기";
        internal static string Normal(string text){return Regex.Replace(text??"",@"[^가-힣]","");}
        internal static RectangleF? LabelBounds(OcrResult ocr,string label){var lines=ocr.Lines.Where(l=>Normal(l.Text)==Normal(label)).ToArray();if(lines.Length!=1)return null;var words=lines[0].Words.Where(w=>Regex.IsMatch(w.Text,"[가-힣]")).ToArray();if(words.Length==0)return null;double x=words.Min(w=>w.BoundingRect.X),y=words.Min(w=>w.BoundingRect.Y),r=words.Max(w=>w.BoundingRect.Right),b=words.Max(w=>w.BoundingRect.Bottom);return RectangleF.FromLTRB((float)x,(float)y,(float)r,(float)b);}
        internal static async Task<OcrResult> Ocr(Bitmap image,CancellationToken token){var engine=OcrEngine.TryCreateFromLanguage(new Language("ko"));if(engine==null)throw new InvalidOperationException("Korean OCR unavailable");int width=image.Width,height=image.Height;var bits=image.LockBits(new Rectangle(0,0,width,height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var pixels=new byte[width*height*4];try{for(int y=0;y<height;y++)Marshal.Copy(IntPtr.Add(bits.Scan0,y*bits.Stride),pixels,y*width*4,width*4);}finally{image.UnlockBits(bits);}if((image.GetPixel(0,0).R+image.GetPixel(width-1,0).R)/2<110){for(int i=0;i<pixels.Length;i+=4){pixels[i]=(byte)(255-pixels[i]);pixels[i+1]=(byte)(255-pixels[i+1]);pixels[i+2]=(byte)(255-pixels[i+2]);}}token.ThrowIfCancellationRequested();using(var software=SoftwareBitmap.CreateCopyFromBuffer(pixels.AsBuffer(),BitmapPixelFormat.Bgra8,width,height,BitmapAlphaMode.Ignore)){var result=await engine.RecognizeAsync(software).AsTask(token);token.ThrowIfCancellationRequested();return result;}}
        static double Distance(double x,double y,double ax,double ay,double bx,double by){double vx=bx-ax,vy=by-ay,t=Math.Max(0,Math.Min(1,((x-ax)*vx+(y-ay)*vy)/(vx*vx+vy*vy)));return Math.Sqrt(Math.Pow(x-ax-t*vx,2)+Math.Pow(y-ay-t*vy,2));}
        static bool Yellow(Color c){return c.R>210&&c.G>165&&c.B<125;}
        // Require a round yellow component AND both arms of a black check, not a dot/cross.
        internal static int Marker(Bitmap image,RectangleF label){double h=label.Height;if(h<7||h>70||label.Width<h*6)return 0;var roi=Rectangle.FromLTRB((int)Math.Floor(label.Left-h*2.8),(int)Math.Floor(label.Top-h*.8),(int)Math.Ceiling(label.Left-h*.25),(int)Math.Ceiling(label.Bottom+h*.8));if(roi.Left<0||roi.Top<0||roi.Right>=image.Width||roi.Bottom>=image.Height)return 0;
            var seen=new bool[roi.Width,roi.Height];var components=new List<Rectangle>();for(int y=0;y<roi.Height;y++)for(int x=0;x<roi.Width;x++){if(seen[x,y]||!Yellow(image.GetPixel(roi.X+x,roi.Y+y)))continue;var queue=new Queue<Point>();queue.Enqueue(new Point(x,y));seen[x,y]=true;int l=x,r=x,t=y,b=y,count=0;while(queue.Count>0){var p=queue.Dequeue();count++;l=Math.Min(l,p.X);r=Math.Max(r,p.X);t=Math.Min(t,p.Y);b=Math.Max(b,p.Y);foreach(var d in new[]{new Point(-1,0),new Point(1,0),new Point(0,-1),new Point(0,1)}){int nx=p.X+d.X,ny=p.Y+d.Y;if(nx<0||ny<0||nx>=roi.Width||ny>=roi.Height||seen[nx,ny])continue;seen[nx,ny]=true;if(Yellow(image.GetPixel(roi.X+nx,roi.Y+ny)))queue.Enqueue(new Point(nx,ny));}}if(count>=h*h*.35){var box=new Rectangle(roi.X+l,roi.Y+t,r-l+1,b-t+1);double ratio=(double)box.Width/box.Height;if(ratio>.78&&ratio<1.24&&box.Height>h*.8&&box.Height<h*2.4&&Math.Abs(box.Top+box.Height*.5-(label.Top+label.Height*.5))<h*.65)components.Add(box);}}
            if(components.Count>1)return 0;if(components.Count==1){var box=components[0];var dark=new List<PointF>();int yellow=0;for(int y=0;y<box.Height;y++)for(int x=0;x<box.Width;x++){var c=image.GetPixel(box.X+x,box.Y+y);if(Yellow(c))yellow++;if(c.R<110&&c.G<110&&c.B<110&&Math.Pow((x-box.Width*.5)/box.Width,2)+Math.Pow((y-box.Height*.5)/box.Height,2)<.20)dark.Add(new PointF((float)(x*24.0/box.Width),(float)(y*24.0/box.Height)));}if(yellow<box.Width*box.Height*.46||yellow>box.Width*box.Height*.88||dark.Count<box.Width*box.Height*.015||dark.Count>box.Width*box.Height*.19)return 0;
                int near=0;foreach(var p in dark)if(Math.Min(Distance(p.X,p.Y,6,11,10,15),Distance(p.X,p.Y,10,15,17,7))<=2.8)near++;if(near<dark.Count*.88)return 0;
                int armA=0,armB=0;for(int k=0;k<5;k++){float x=6+k,y=11+k;if(dark.Any(p=>Math.Abs(p.X-x)<=2&&Math.Abs(p.Y-y)<=2))armA++;}for(int k=0;k<8;k++){float x=10+k,y=15-k*8f/7;if(dark.Any(p=>Math.Abs(p.X-x)<=2&&Math.Abs(p.Y-y)<=2))armB++;}return armA>=4&&armB>=7?1:0;
            }
            // OFF is only a conservative indication; every other drawing stays UNKNOWN.
            int gray=0,white=0,total=roi.Width*roi.Height;for(int y=roi.Top;y<roi.Bottom;y++)for(int x=roi.Left;x<roi.Right;x++){var c=image.GetPixel(x,y);if(Math.Abs(c.R-c.G)<12&&Math.Abs(c.R-c.B)<12&&c.R>=100&&c.R<220)gray++;if(c.R>235&&c.G>235&&c.B>235)white++;}return gray>h*1.5&&white>total*.75?-1:0;
        }
        internal static async Task<int> Read(Bitmap image,CancellationToken token){int observed=0;foreach(int target in new[]{1120,1680,2240}){int width=target,height=(int)Math.Round(image.Height*(double)width/image.Width);int maximum=(int)OcrEngine.MaxImageDimension;if(Math.Max(width,height)>maximum){double factor=(double)maximum/Math.Max(width,height);width=(int)(width*factor);height=(int)(height*factor);}using(var normalized=Resize(image,Math.Max(1,width),Math.Max(1,height))){var ocr=await Ocr(normalized,token);if(ocr.Lines.Count(l=>Normal(l.Text)==Normal(Label))>1)return 0;var bounds=LabelBounds(ocr,Label);int state=bounds.HasValue?Marker(normalized,bounds.Value):0;if(state!=0){if(observed!=0&&observed!=state)return 0;observed=state;}}}return observed;}
        internal static Bitmap Resize(Bitmap source,int w,int h){var result=new Bitmap(w,h,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(result)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(source,new Rectangle(0,0,w,h));}return result;}
        static bool[] Mask(Bitmap image){var result=new bool[24*24];int bg=(image.GetPixel(0,0).R+image.GetPixel(23,0).R+image.GetPixel(0,23).R+image.GetPixel(23,23).R)/4;for(int y=0;y<24;y++)for(int x=0;x<24;x++)result[y*24+x]=Math.Abs(image.GetPixel(x,y).R-bg)>20;return result;}
        internal static Point? Gear(Bitmap sidebar,float scale){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("AgitCon.KakaoSettingsGear.png")){if(stream==null)return null;using(var original=new Bitmap(stream)){int width=sidebar.Width,height=sidebar.Height;var shade=new byte[width*height];var data=sidebar.LockBits(new Rectangle(0,0,width,height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var row=new byte[width*4];for(int y=0;y<height;y++){Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),row,0,row.Length);for(int x=0;x<width;x++)shade[y*width+x]=row[x*4+2];}}finally{sidebar.UnlockBits(data);}int background=(shade[0]+shade[width-1]+shade[(height-1)*width]+shade[height*width-1])/4;var seen=new bool[shade.Length];var boxes=new List<Rectangle>();int[] offsets={-1,0,1};for(int y=height/3;y<height;y++)for(int x=0;x<width;x++){int index=y*width+x;if(seen[index]||Math.Abs(shade[index]-background)<=20)continue;int l=x,r=x,t=y,b=y;var queue=new Queue<Point>();queue.Enqueue(new Point(x,y));seen[index]=true;while(queue.Count>0){var point=queue.Dequeue();l=Math.Min(l,point.X);r=Math.Max(r,point.X);t=Math.Min(t,point.Y);b=Math.Max(b,point.Y);foreach(int dy in offsets)foreach(int dx in offsets){if(dx==0&&dy==0)continue;int xx=point.X+dx,yy=point.Y+dy;if(xx<0||yy<0||xx>=width||yy>=height)continue;int next=yy*width+xx;if(seen[next])continue;seen[next]=true;if(Math.Abs(shade[next]-background)>20)queue.Enqueue(new Point(xx,yy));}}if(r-l>=8&&b-t>=8&&r-l<=110&&b-t<=110)boxes.Add(new Rectangle(l,t,r-l+1,b-t+1));}
            var referenceMask=Mask(original);int refLeft=24,refTop=24,refRight=0,refBottom=0;for(int y=0;y<24;y++)for(int x=0;x<24;x++)if(referenceMask[y*24+x]){refLeft=Math.Min(refLeft,x);refTop=Math.Min(refTop,y);refRight=Math.Max(refRight,x);refBottom=Math.Max(refBottom,y);}var hits=new List<Point>();foreach(var box in boxes){double estimate=24.0*Math.Max((double)box.Width/(refRight-refLeft+1),(double)box.Height/(refBottom-refTop+1));for(int size=Math.Max(18,(int)Math.Round(estimate)-2);size<=Math.Min(104,(int)Math.Round(estimate)+2);size++){bool[] reference;using(var resized=Resize(original,size,size)){int bg=(resized.GetPixel(0,0).R+resized.GetPixel(size-1,0).R+resized.GetPixel(0,size-1).R+resized.GetPixel(size-1,size-1).R)/4;reference=new bool[576];for(int yy=0;yy<24;yy++)for(int xx=0;xx<24;xx++)reference[yy*24+xx]=Math.Abs(resized.GetPixel(xx*(size-1)/23,yy*(size-1)/23).R-bg)>20;}int left=box.Left-(int)Math.Round(refLeft*size/24.0),top=box.Top-(int)Math.Round(refTop*size/24.0);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int px=left+dx,py=top+dy;if(px<0||py<0||px+size>width||py+size>height)continue;int bg=(shade[py*width+px]+shade[py*width+px+size-1]+shade[(py+size-1)*width+px]+shade[(py+size-1)*width+px+size-1])/4,both=0,either=0;for(int yy=0;yy<24;yy++)for(int xx=0;xx<24;xx++){bool ink=Math.Abs(shade[(py+yy*(size-1)/23)*width+px+xx*(size-1)/23]-bg)>20,wanted=reference[yy*24+xx];if(ink&&wanted)both++;if(ink||wanted)either++;}if(either>15&&(double)both/either>.76)hits.Add(new Point(px+size/2,py+size/2));}}}
            if(hits.Count==0)return null;var first=hits[0];if(hits.Any(p=>Math.Abs(p.X-first.X)>16*scale||Math.Abs(p.Y-first.Y)>16*scale))return null;return new Point((int)hits.Average(p=>p.X),(int)hits.Average(p=>p.Y));}}}
    }
}
